"120 :   static TernaryValue getPureBooleanValue(Node n) {
121 :     switch (n.getType()) {
122 :       case Token.STRING:
123 :         return TernaryValue.forBoolean(n.getString().length() > 0);
124 : 
125 :       case Token.NUMBER:
126 :         return TernaryValue.forBoolean(n.getDouble() != 0);
127 : 
128 :       case Token.NOT:
129 :         return getPureBooleanValue(n.getLastChild()).not();
130 : 
131 :       case Token.NULL:
132 :       case Token.FALSE:
133 :         return TernaryValue.FALSE;
134 : 
135 :       case Token.VOID:
136 :           return TernaryValue.FALSE;
137 : 
138 :       case Token.NAME:
139 :         String name = n.getString();
140 :         if ("undefined".equals(name)
141 :             || "NaN".equals(name)) {
142 :           // We assume here that programs don't change the value of the keyword
143 :           // undefined to something other than the value undefined.
144 :           return TernaryValue.FALSE;
145 :         } else if ("Infinity".equals(name)) {
146 :           return TernaryValue.TRUE;
147 :         }
148 :         break;
149 : 
150 :       case Token.TRUE:
151 :       case Token.REGEXP:
152 :         return TernaryValue.TRUE;
153 : 
154 :       case Token.ARRAYLIT:
155 :       case Token.OBJECTLIT:
156 :         if (!mayHaveSideEffects(n)) {
157 :           return TernaryValue.TRUE;
158 :         }
159 :         break;
160 :     }
161 : 
162 :     return TernaryValue.UNKNOWN;
163 :   }"

