"164 :   private Node tryFoldImmediateCallToBoundFunction(Node n) {
165 :     // Rewriting "(fn.bind(a,b))()" to "fn.call(a,b)" makes it inlinable
166 :     Preconditions.checkState(n.getType() == Token.CALL);
167 :     Node callTarget = n.getFirstChild();
168 :     Bind bind = getCodingConvention().describeFunctionBind(callTarget);
169 :     if (bind != null) {
170 :       // replace the call target
171 :       bind.target.detachFromParent();
172 :       n.replaceChild(callTarget, bind.target);
173 :       callTarget = bind.target;
174 : 
175 :       // push the parameters
176 :       addParameterAfter(bind.parameters, callTarget);
177 : 
178 :       // add the this value before the parameters if necessary
179 :       if (bind.thisValue != null && !NodeUtil.isUndefined(bind.thisValue)) {
180 :         // rewrite from "fn(a, b)" to "fn.call(thisValue, a, b)"
181 :         Node newCallTarget = new Node(Token.GETPROP,
182 :             callTarget.cloneTree(),
183 :             Node.newString("call").copyInformationFrom(callTarget));
184 :         n.replaceChild(callTarget, newCallTarget);
185 :         n.addChildAfter(bind.thisValue.cloneTree(), newCallTarget);
186 :         n.putBooleanProp(Node.FREE_CALL, false);
187 :       } else {
188 :         n.putBooleanProp(Node.FREE_CALL, true);
189 :       }
190 :       reportCodeChange();
191 :     }
192 :     return n;
193 :   }"

